{"edits":[{"path":"scripts/lib/reliability-aggregation.mjs","content":"// Reliability aggregation primitives for the Agent Dev benefit report.
//
// Contract (see harness/specs/rules/reliability-aggregation-boundary.md):
// - pass^k  = share of COMPLETE cases where all k trials passed.
// - pass@k  = share of COMPLETE cases where at least one trial passed.
//   The two metrics are never mixed or substituted for one another.
// - A case with a missing / timeout / crashed / skipped trial is INCOMPLETE:
//   it is excluded from every denominator but is always retained in the report.
// - flake = a complete case whose FIRST trial failed and whose later fixed
//   re-runs passed. The first failure is preserved; a successful retry never
//   washes out the original gate failure.
// - positive anchors must pass on every trial; negative anchors must reject on
//   every trial. Any violation forces gate = 'fail'.
// - Fewer complete cases than the pre-registered design gate (k = 3, >= 20)
//   yields gate = 'insufficient-sample'. A small sample is never reported as PASS.

// No network, process, or timer side effects: this module is pure data work.

export const CONCLUSIVE_STATUSES = Object.freeze(['passed', 'failed']);
export const INCOMPLETE_STATUSES = Object.freeze(['missing', 'timeout', 'crashed', 'skipped']);

export const DEFAULT_RELIABILITY_POLICY = Object.freeze({
  k: 3,
  minCases: 20,
  flakeThreshold: 0,
});

const CONCLUSIVE_SET = new Set(CONCLUSIVE_STATUSES);
const INCOMPLETE_SET = new Set(INCOMPLETE_STATUSES);

function normalizeStatus(value) {
  if (typeof value !== 'string') return 'missing';
  const status = value.trim().toLowerCase();
  return status === '' ? 'missing' : status;
}

function round4(value) {
  return Math.round(value * 10000) / 10000;
}

function rateOf(numerator, denominator) {
  return denominator > 0 ? round4(numerator / denominator) : null;
}

function toCount(value, fallback) {
  const numeric = Number(value);
  if (!Number.isFinite(numeric)) return fallback;
  return Math.trunc(numeric);
}

function summarizeCase(rawCase, k) {
  const id = typeof rawCase?.id === 'string' && rawCase.id !== '' ? rawCase.id : 'unknown';
  const rawTrials = Array.isArray(rawCase?.trials) ? rawCase.trials : [];
  const trials = [];
  for (let index = 0; index < k; index += 1) {
    const trial = rawTrials[index];
    if (trial === undefined || trial === null) {
      trials.push({ index, status: 'missing', outcome: null, detail: 'trial-not-recorded' });
      continue;
    }
    trials.push({
      index,
      status: normalizeStatus(trial.status),
      outcome: trial.outcome === undefined ? null : trial.outcome,
      detail: trial.detail === undefined ? null : trial.detail,
    });
  }

  const extraTrials = Math.max(0, rawTrials.length - k);
  const statuses = trials.map((trial) => trial.status);
  const passedTrials = statuses.filter((status) => status === 'passed').length;
  const failedTrials = statuses.filter((status) => status === 'failed').length;
  const conclusiveTrials = statuses.filter((status) => CONCLUSIVE_SET.has(status)).length;

  const reasons = [];
  for (const status of statuses) {
    if (INCOMPLETE_SET.has(status) && !reasons.includes(status)) reasons.push(status);
  }
  if (extraTrials > 0) reasons.push('extra-trials');

  const complete = conclusiveTrials === k && extraTrials === 0;
  const allPassed = statuses.every((status) => status === 'passed');
  const anyPassed = passedTrials > 0;
  const firstTrialStatus = statuses[0] ?? 'missing';
  const firstTrialPassed = firstTrialStatus === 'passed';
  const flake = firstTrialStatus === 'failed' && anyPassed;

  const anchor = rawCase?.anchor === 'positive' || rawCase?.anchor === 'negative' ? rawCase.anchor : null;
  const safeRequired = rawCase?.safeRequired === true;

  let anchorSatisfied = null;
  if (anchor === 'positive') {
    anchorSatisfied = allPassed && trials.every((trial) => trial.outcome !== 'rejected');
  } else if (anchor === 'negative') {
    anchorSatisfied = allPassed && trials.every((trial) => trial.outcome === 'rejected');
  }

  return {
    id,
    anchor,
    safeRequired,
    complete,
    incompleteReasons: reasons,
    trials,
    statuses,
    passedTrials,
    failedTrials,
    conclusiveTrials,
    allPassed,
    anyPassed,
    firstTrialStatus,
    // Preserved original failure: a later successful retry does not erase it.
    firstFailure: !firstTrialPassed,
    flake,
    anchorSatisfied,
  };
}

export function aggregateReliability(input, options = {}) {
  const source = Array.isArray(input) ? { cases: input } : (input ?? {});
  const optionPolicy = options && typeof options === 'object' && options.policy ? options.policy : {};
  const mergedPolicy = {
    ...DEFAULT_RELIABILITY_POLICY,
    ...(source.policy ?? {}),
    ...optionPolicy,
  };

  const k = Math.max(1, toCount(mergedPolicy.k, DEFAULT_RELIABILITY_POLICY.k));
  const minCases = Math.max(0, toCount(mergedPolicy.minCases, DEFAULT_RELIABILITY_POLICY.minCases));
  const flakeThreshold = Number.isFinite(Number(mergedPolicy.flakeThreshold))
    ? Number(mergedPolicy.flakeThreshold)
    : DEFAULT_RELIABILITY_POLICY.flakeThreshold;

  const rawCases = Array.isArray(source.cases) ? source.cases : [];
  const summaries = rawCases.map((rawCase) => summarizeCase(rawCase, k));
  const completeCases = summaries.filter((summary) => summary.complete);
  const incompleteCases = summaries.filter((summary) => !summary.complete);

  const totals = {
    cases: summaries.length,
    completeCases: completeCases.length,
    incompleteCases: incompleteCases.length,
    missing: 0,
    timeout: 0,
    crashed: 0,
    skipped: 0,
  };
  for (const status of INCOMPLETE_STATUSES) {
    totals[status] = incompleteCases.filter((summary) => summary.incompleteReasons.includes(status)).length;
  }

  const passPowKNumerator = completeCases.filter((summary) => summary.allPassed).length;
  const passAtKNumerator = completeCases.filter((summary) => summary.anyPassed).length;
  const completeTrialDenominator = completeCases.reduce((sum, summary) => sum + summary.conclusiveTrials, 0);
  const completeTrialNumerator = completeCases.reduce((sum, summary) => sum + summary.passedTrials, 0);
  const observedTrialDenominator = summaries.reduce((sum, summary) => sum + summary.conclusiveTrials, 0);
  const observedTrialNumerator = summaries.reduce((sum, summary) => sum + summary.passedTrials, 0);

  const flakeComplete = completeCases.filter((summary) => summary.flake);
  const flakeAll = summaries.filter((summary) => summary.flake);

  const anchorViolations = { positive: [], negative: [] };
  for (const summary of summaries) {
    if (!summary.anchor) continue;
    if (summary.anchorSatisfied !== true) {
      anchorViolations[summary.anchor].push({
        id: summary.id,
        reason: summary.anchor === 'negative'
          ? 'negative-anchor-must-reject-on-every-trial'
          : 'positive-anchor-must-pass-on-every-trial',
        statuses: summary.statuses.slice(),
      });
    }
  }

  const safeRequiredViolations = [];
  for (const summary of summaries) {
    if (!summary.safeRequired) continue;
    if (!summary.complete) {
      safeRequiredViolations.push({ id: summary.id, reason: 'safe-required-case-incomplete', details: summary.incompleteReasons.slice() });
    }
    if (summary.flake) {
      safeRequiredViolations.push({ id: summary.id, reason: 'safe-required-case-flaky' });
    }
    if (!summary.allPassed) {
      safeRequiredViolations.push({ id: summary.id, reason: 'safe-required-case-not-all-passed', statuses: summary.statuses.slice() });
    }
    if (summary.incompleteReasons.includes('skipped')) {
      safeRequiredViolations.push({ id: summary.id, reason: 'safe-required-case-skipped' });
    }
  }

  const gateReasons = [];
  let gateStatus = 'pass';

  const totalAnchorViolations = anchorViolations.positive.length + anchorViolations.negative.length;
  if (totalAnchorViolations > 0) {
    gateStatus = 'fail';
    gateReasons.push({
      code: 'anchor-violation',
      detail: `anchor violations: ${totalAnchorViolations}`,
      violations: [...anchorViolations.positive, ...anchorViolations.negative],
    });
  }

  if (safeRequiredViolations.length > 0) {
    gateStatus = 'fail';
    gateReasons.push({
      code: 'safe-required-not-clean',
      detail: `safe required cases must have 0 skip and 0 flake (violations: ${safeRequiredViolations.length})`,
      violations: safeRequiredViolations,
    });
  }

  if (gateStatus === 'pass') {
    if (completeCases.length < minCases) {
      gateStatus = 'insufficient-sample';
      gateReasons.push({
        code: 'insufficient-sample',
        detail: `complete cases ${completeCases.length} < pre-registered design gate ${minCases} (k=${k})`,
      });
    } else if (flakeComplete.length > 0 && rateOf(flakeComplete.length, completeCases.length) > flakeThreshold) {
      gateStatus = 'fail';
      gateReasons.push({
        code: 'flake-threshold-exceeded',
        detail: `flake rate ${rateOf(flakeComplete.length, completeCases.length)} > pre-registered threshold ${flakeThreshold}`,
        cases: flakeComplete.map((summary) => summary.id),
      });
    } else if (completeCases.some((summary) => !summary.allPassed)) {
      gateStatus = 'fail';
      gateReasons.push({
        code: 'case-not-deterministic',
        detail: 'at least one complete case did not pass every trial',
        cases: completeCases.filter((summary) => !summary.allPassed).map((summary) => summary.id),
      });
    }
  }

  return {
    policy: { k, minCases, flakeThreshold },
    totals,
    denominators: {
      completeCases: completeCases.length,
      excludedIncompleteCases: incompleteCases.length,
    },
    passPowK: {
      definition: 'share of complete cases where all k trials passed',
      numerator: passPowKNumerator,
      denominator: completeCases.length,
      rate: rateOf(passPowKNumerator, completeCases.length),
    },
    passAtK: {
      definition: 'share of complete cases where at least one trial passed',
      numerator: passAtKNumerator,
      denominator: completeCases.length,
      rate: rateOf(passAtKNumerator, completeCases.length),
    },
    trialSuccessRate: {
      definition: 'passed trials / conclusive trials across complete cases',
      numerator: completeTrialNumerator,
      denominator: completeTrialDenominator,
      rate: rateOf(completeTrialNumerator, completeTrialDenominator),
    },
    trialSuccessRateAllObserved: {
      definition: 'passed trials / conclusive trials across every recorded trial (includes incomplete cases)',
      numerator: observedTrialNumerator,
      denominator: observedTrialDenominator,
      rate: rateOf(observedTrialNumerator, observedTrialDenominator),
    },
    flake: {
      definition: 'share of complete cases whose first trial failed and whose later fixed re-runs passed',
      count: flakeComplete.length,
      denominator: completeCases.length,
      rate: rateOf(flakeComplete.length, completeCases.length),
      cases: flakeComplete.map((summary) => summary.id),
      allObservedCases: flakeAll.map((summary) => summary.id),
    },
    incomplete: {
      definition: 'cases with missing / timeout / crashed / skipped trials: excluded from denominators, retained here',
      count: incompleteCases.length,
      cases: incompleteCases.map((summary) => ({
        id: summary.id,
        reasons: summary.incompleteReasons.slice(),
        statuses: summary.statuses.slice(),
      })),
    },
    anchors: {
      positive: {
        expected: 'every trial passes and is not rejected',
        count: summaries.filter((summary) => summary.anchor === 'positive').length,
        violations: anchorViolations.positive,
      },
      negative: {
        expected: 'every trial rejects',
        count: summaries.filter((summary) => summary.anchor === 'negative').length,
        violations: anchorViolations.negative,
      },
    },
    safeRequired: {
      expected: '0 skip and 0 flake',
      count: summaries.filter((summary) => summary.safeRequired).length,
      violations: safeRequiredViolations,
    },
    cases: summaries.map((summary) => ({
      id: summary.id,
      anchor: summary.anchor,
      safeRequired: summary.safeRequired,
      complete: summary.complete,
      incompleteReasons: summary.incompleteReasons.slice(),
      passedTrials: summary.passedTrials,
      failedTrials: summary.failedTrials,
      allPassed: summary.allPassed,
      anyPassed: summary.anyPassed,
      firstTrialStatus: summary.firstTrialStatus,
      firstFailure: summary.firstFailure,
      flake: summary.flake,
      anchorSatisfied: summary.anchorSatisfied,
    })),
    gate: {
      status: gateStatus,
      reasons: gateReasons,
    },
  };
}

export default aggregateReliability;
"},{"path":"scripts/lib/reliability-aggregation.d.mts","content":"/**
 * Type declarations for scripts/lib/reliability-aggregation.mjs
 *
 * pass^k and pass@k are intentionally separate shapes so they can never be
 * mixed up: passPowK requires every trial to pass, passAtK requires at least one.
 */

export type TrialStatus = 'passed' | 'failed' | 'missing' | 'timeout' | 'crashed' | 'skipped';
export type TrialOutcome = 'accepted' | 'rejected' | null;

export interface ReliabilityPolicy {
  k: number;
  minCases: number;
  flakeThreshold: number;
}

export interface ReliabilityTrial {
  status: TrialStatus;
  outcome?: TrialOutcome;
  detail?: string | null;
}

export interface ReliabilityCase {
  id: string;
  anchor?: 'positive' | 'negative' | null;
  safeRequired?: boolean;
  trials: ReliabilityTrial[];
}

export interface ReliabilityFixture {
  policy: Partial<ReliabilityPolicy>;
  cases: ReliabilityCase[];
  controls?: Record<string, { cases: ReliabilityCase[] }>;
  expectedControlGates?: Record<string, string>;
}

export interface ReliabilityRate {
  numerator: number;
  denominator: number;
  rate: number | null;
}

export interface ReliabilityMetric extends ReliabilityRate {
  definition: string;
}

export interface ReliabilityCaseSummary {
  id: string;
  anchor: 'positive' | 'negative' | null;
  safeRequired: boolean;
  complete: boolean;
  incompleteReasons: string[];
  passedTrials: number;
  failedTrials: number;
  allPassed: boolean;
  anyPassed: boolean;
  firstTrialStatus: TrialStatus;
  firstFailure: boolean;
  flake: boolean;
  anchorSatisfied: boolean | null;
}

export interface ReliabilityAnchorReport {
  expected: string;
