    policy: { k, minCases, flakeThreshold },
    totals,
    denominators: {
      completeCases: completeCases.length,
      excludedIncompleteCases: incompleteCases.length,
    },
    passPowK: {
      definition: 'share of complete cases where all k trials passed',
      numerator: passPowKNumerator,
      denominator: completeCases.length,
      rate: rateOf(passPowKNumerator, completeCases.length),
    },
    passAtK: {
      definition: 'share of complete cases where at least one trial passed',
      numerator: passAtKNumerator,
      denominator: completeCases.length,
      rate: rateOf(passAtKNumerator, completeCases.length),
    },
    trialSuccessRate: {
      definition: 'passed trials / conclusive trials across complete cases',
      numerator: completeTrialNumerator,
      denominator: completeTrialDenominator,
      rate: rateOf(completeTrialNumerator, completeTrialDenominator),
    },
    trialSuccessRateAllObserved: {
      definition: 'passed trials / conclusive trials across every recorded trial (includes incomplete cases)',
      numerator: observedTrialNumerator,
      denominator: observedTrialDenominator,
      rate: rateOf(observedTrialNumerator, observedTrialDenominator),
    },
    flake: {
      definition: 'share of complete cases whose first trial failed and whose later fixed re-runs passed',
      count: flakeComplete.length,
      denominator: completeCases.length,
      rate: rateOf(flakeComplete.length, completeCases.length),
      cases: flakeComplete.map((summary) => summary.id),
      allObservedCases: flakeAll.map((summary) => summary.id),
    },
    incomplete: {
      definition: 'cases with missing / timeout / crashed / skipped trials: excluded from denominators, retained here',
      count: incompleteCases.length,
      cases: incompleteCases.map((summary) => ({
        id: summary.id,
        reasons: summary.incompleteReasons.slice(),
        statuses: summary.statuses.slice(),
      })),
    },
    anchors: {
      positive: {
        expected: 'every trial passes and is not rejected',
        count: summaries.filter((summary) => summary.anchor === 'positive').length,
        violations: anchorViolations.positive,
      },
      negative: {
        expected: 'every trial rejects',
        count: summaries.filter((summary) => summary.anchor === 'negative').length,
        violations: anchorViolations.negative,
      },
    },
    safeRequired: {
      expected: '0 skip and 0 flake',
      count: summaries.filter((summary) => summary.safeRequired).length,
      violations: safeRequiredViolations,
    },
    cases: summaries.map((summary) => ({
      id: summary.id,
      anchor: summary.anchor,
      safeRequired: summary.safeRequired,
      complete: summary.complete,
      incompleteReasons: summary.incompleteReasons.slice(),
      passedTrials: summary.passedTrials,
      failedTrials: summary.failedTrials,
      allPassed: summary.allPassed,
      anyPassed: summary.anyPassed,
      firstTrialStatus: summary.firstTrialStatus,
      firstFailure: summary.firstFailure,
      flake: summary.flake,
      anchorSatisfied: summary.anchorSatisfied,
    })),
    gate: {
      status: gateStatus,
      reasons: gateReasons,
    },
  };
}

export default aggregateReliability;
